  function shouldInvoke(time) {
    if (lastArgs === undefined) return false;
    const timeSinceLastCall = time - (lastArgs.timestamp || 0);
    return timeSinceLastCall >= delay;
  }

  const debounced = function (...args) {
    const time = Date.now();
    lastArgs = { args, timestamp: time };
    lastThis = this;

    clearTimeout(timeoutId);

    if (options.maxWait) {
      clearTimeout(maxTimeoutId);
      maxTimeoutId = setTimeout(() => {
        if (shouldInvoke(Date.now())) {
          invokeFunc(true);
        }
      }, options.maxWait);
    }

    timeoutId = setTimeout(() => {
      invokeFunc(true);
    }, delay);

    return result;
  };

  // Cancel pending invocation
  debounced.cancel = () => {
    clearTimeout(timeoutId);
    clearTimeout(maxTimeoutId);
    lastArgs = lastThis = undefined;
  };

  // Invoke immediately
  debounced.flush = () => {
    return lastArgs === undefined ? result : invokeFunc(true);
  };

  return debounced;
}
```

